const { test } = require('node:test');
const assert = require('node:assert/strict');
const { slugify } = require('./slugify');

test('converts a simple title to a slug', () => {
  assert.equal(slugify('Hello World'), 'hello-world');
});

test('folds accents and trims surrounding whitespace', () => {
  assert.equal(slugify('  Café Déjà Vu!! '), 'cafe-deja-vu');
});

test('leaves an already-slugged string unchanged', () => {
  assert.equal(slugify('Already-slugged'), 'already-slugged');
});

test('collapses runs of punctuation and whitespace to one dash', () => {
  assert.equal(slugify('a --- b'), 'a-b');
});

test('preserves digits', () => {
  assert.equal(slugify('Top 10 Tips'), 'top-10-tips');
});

test('returns an empty string for empty input', () => {
  assert.equal(slugify(''), '');
});

test('returns an empty string when input has no alphanumerics', () => {
  assert.equal(slugify('!!!'), '');
});

test('throws a TypeError for non-string input', () => {
  assert.throws(() => slugify(null), TypeError);
  assert.throws(() => slugify(42), TypeError);
  assert.throws(() => slugify(undefined), TypeError);
});

/**
 * Convert a title into a URL-safe slug.
 *
 * @param {string} title - The title to convert.
 * @returns {string} The lowercase, dash-separated slug.
 * @throws {TypeError} If `title` is not a string.
 */
function slugify(title) {
  if (typeof title !== 'string') {
    throw new TypeError('slugify expects a string');
  }

  // NFD splits accented characters into a base letter plus a combining mark,
  // so dropping the marks folds them to ASCII instead of discarding the letter.
  return title
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

module.exports = { slugify };

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { truncate } = require('./truncate');

test('returns short input untouched', () => {
  assert.equal(truncate('hello', 10), 'hello');
});

test('returns exact-length input untouched', () => {
  assert.equal(truncate('hello', 5), 'hello');
});

test('truncates with a single-character ellipsis', () => {
  assert.equal(truncate('abcdef', 5), 'abcd…');
  assert.equal(truncate('hello world', 8), 'hello w…');
});

test('a budget of 1 leaves room for the ellipsis only', () => {
  assert.equal(truncate('abc', 1), '…');
});

test('returns empty string for a non-positive budget', () => {
  assert.equal(truncate('abc', 0), '');
  assert.equal(truncate('abc', -3), '');
});

test('handles an empty string', () => {
  assert.equal(truncate('', 5), '');
});

test('result length never exceeds n', () => {
  const result = truncate('abcdef', 5);
  assert.ok(result.length <= 5);
  assert.equal(result.length, 5);
});

test('throws TypeError when text is not a string', () => {
  assert.throws(() => truncate(null, 5), TypeError);
  assert.throws(() => truncate(42, 5), TypeError);
});

test('throws TypeError when n is not an integer', () => {
  assert.throws(() => truncate('abc', '5'), TypeError);
  assert.throws(() => truncate('abc', 2.5), TypeError);
  assert.throws(() => truncate('abc', NaN), TypeError);
});

const ELLIPSIS = '…';

/**
 * Shorten `text` so the result is never longer than `n` characters.
 *
 * The ellipsis is charged against the budget rather than appended to it, so
 * the return value fits a hard width limit (table cells, fixed-width logs)
 * without the caller reserving space for it.
 *
 * @param {string} text - The string to shorten.
 * @param {number} n - Maximum length of the result, in characters.
 * @returns {string} `text` unchanged when it already fits, otherwise a
 *   truncation of exactly `n` characters ending in a single-character
 *   ellipsis.
 * @throws {TypeError} If `text` is not a string or `n` is not an integer.
 */
function truncate(text, n) {
  if (typeof text !== 'string') {
    throw new TypeError('text must be a string');
  }
  if (!Number.isInteger(n)) {
    throw new TypeError('n must be an integer');
  }
  if (n <= 0) {
    return '';
  }
  if (text.length <= n) {
    return text;
  }
  return text.slice(0, n - 1) + ELLIPSIS;
}

module.exports = { truncate };

